<?php /** @var array $backups @var bool $remoteConfigured @var \Core\Security\Csrf $csrf @var string $basePath @var \Core\Auth\AdminUser $user */ $latest=$backups[0]??null; $bytes=array_sum(array_map(static fn($b)=>(int)$b['size'],$backups)); $verified=count(array_filter($backups,static fn($b)=>$b['verified'])); ?>
<section class="status-strip"><div class="status-chip <?= $backups&&$verified===count($backups)?'ok':'warn' ?>"><strong><?= $verified ?>/<?= count($backups) ?></strong><span>Verified recovery points</span></div><div class="status-chip"><strong><?= $latest ? e(date('M j, Y', (int)$latest['mtime'])) : 'Never' ?></strong><span>Latest backup</span></div><div class="status-chip"><strong><?= e(number_format($bytes/1048576,1)) ?> MB</strong><span>Protected storage</span></div><div class="status-chip <?= $remoteConfigured?'ok':'neutral' ?>"><strong><?= $remoteConfigured?'Configured':'Local only' ?></strong><span>Off-site replication</span></div></section>
<div class="card"><div class="card-heading"><div><h2>Recovery points</h2><p class="card-subtitle">Each archive includes the database, configuration, uploads, protected media, modules, and themes with integrity hashes.</p></div><form method="post" action="<?= e_attr($basePath) ?>/admin/backups/create" data-busy-label="Creating backup…"><?= $csrf->field() ?><button class="btn">Create backup now</button></form></div>
<?php if ($backups === []): ?><div class="empty-state"><strong>No recovery point exists yet</strong><span>Create one before updating modules, themes, Core, or important content.</span></div><?php else: ?><div class="backup-grid"><?php foreach ($backups as $b): ?><article class="backup-card <?= $b['verified']?'is-verified':'is-invalid' ?>"><div class="backup-card-head"><span class="backup-icon" aria-hidden="true">◆</span><div><strong><?= e(date('M j, Y · g:i a',(int)$b['mtime'])) ?></strong><span><?= e($b['name']) ?></span></div><span class="badge <?= $b['verified']?'ok':'bad' ?>"><?= $b['verified']?'Verified':'Invalid' ?></span></div><dl><div><dt>Archive size</dt><dd><?= e(number_format((int)$b['size']/1048576,2)) ?> MB</dd></div><div><dt>Core version</dt><dd><?= e($b['core']??'Unknown') ?></dd></div><div><dt>Database tables</dt><dd><?= (int)$b['tables'] ?></dd></div><div><dt>Protected files</dt><dd><?= (int)$b['files'] ?></dd></div></dl><?php if(!$b['verified']): ?><p class="backup-error"><?= e($b['error']??'Integrity validation failed.') ?></p><?php endif; ?><div class="button-row compact"><?php if ($user->isOwner() && $b['verified']): ?><form method="post" action="<?= e_attr($basePath) ?>/admin/backups/restore" data-busy-label="Restoring…"><?= $csrf->field() ?><input type="hidden" name="name" value="<?= e_attr($b['name']) ?>"><button class="btn small secondary" data-confirm="Restore this verified recovery point? Current data and files will be replaced after a safety snapshot is created.">Restore</button></form><?php endif; ?><form method="post" action="<?= e_attr($basePath) ?>/admin/backups/delete"><?= $csrf->field() ?><input type="hidden" name="name" value="<?= e_attr($b['name']) ?>"><button class="btn small danger" data-confirm="Permanently delete this recovery point?">Delete</button></form></div></article><?php endforeach; ?></div><?php endif; ?></div>
<details class="help-panel"><summary>What happens during a restore?</summary><div>Core first creates a safety snapshot, enables maintenance mode, validates the archive and file hashes, restores the matching database and files, then returns the site to its prior maintenance state. Only owners can restore.</div></details>
